using System.IO;
using System.Collections.Generic;
using System.Linq;
using NeoCompose.Runtime;
using NeoCompose.Runtime.Json;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

namespace NeoCompose.Tests
{
    /// <summary>
    /// Newtonsoft.Json round-trip coverage for <see cref="ProjectData"/>
    /// and the full IR tree rooted on <see cref="Member.getter"/>.
    ///
    /// Two fixtures back the suite:
    ///
    ///  - <c>synth-example.json</c> — generated by the TS-side dump
    ///    script (`scripts/dump-synth-export.ts`). Designed to exercise
    ///    every IR variant: list / dict literals, force-unwrap,
    ///    isCheck, callGetter, coalesce, where / count functions, both
    ///    arithmetic + boolean operations, and the four instruction
    ///    kinds (variable / if / return / throw, plus the bare
    ///    <c>return;</c> null-pointer case).
    ///  - <c>project-example.json</c> — a real-world export captured
    ///    from a live Neo-Compose authoring session.
    ///
    /// Tests load each fixture from
    /// <c>Packages/com.ryanbliss.neocompose/Tests/</c> (the canonical
    /// Unity Package Manager path for local-path references and
    /// registry installs alike) and pass the JSON through
    /// <see cref="JsonConvert.DeserializeObject{T}(string)"/>.
    /// </summary>
    public class ProjectExportRoundTripTests
    {
        private const string PackageRoot =
            "Packages/com.ryanbliss.neocompose/Tests";

        private const string P61MaterializedTrackId =
            "a03e2c7d-7fe5-5efc-8a6f-12a8484e3a8e";

        private const string P61MaterializedSegmentId =
            "be79664a-a0ae-53f6-9a45-97360120f919";

        private const string P61FirstUnorderedFrameId =
            "bbbb0005-0000-4000-8000-000000000005";

        private const string P61SecondUnorderedFrameId =
            "bbbb0006-0000-4000-8000-000000000006";

        private static string LoadFixture(string fileName)
        {
            return File.ReadAllText(Path.Combine(PackageRoot, fileName));
        }

        private static ProjectData Deserialize(string json)
        {
            var root = JObject.Parse(json);
            root["metadata"] ??= new JObject
            {
                ["schemaVersion"] = NeoProjectExportContract.CurrentSchemaVersion,
                ["projectId"] = "unit-test-project",
                ["versionId"] = "unit-test-version",
            };
            root["variantFolders"] ??= new JObject();
            return JsonConvert.DeserializeObject<ProjectData>(root.ToString());
        }

        /// <summary>
        /// P61 section 10 cross-repository fixture. The Neo CLI generates this
        /// export from the segment rig after materializing a required-constructor
        /// track, its nested required-constructor segment, and two constructed
        /// entries in a genuine unordered list. Unity must consume that exact
        /// materialized wire shape (restamped to the current schema version)
        /// without retaining executable row initializers.
        /// </summary>
        [Test]
        public void P61SegmentRig_MaterializedConstructorRowsLoadAtTheCurrentSchema()
        {
            string json = LoadFixture("p61-segment-rig-schema17.json");
            ProjectData data = Deserialize(json);

            Assert.AreEqual(
                NeoProjectExportContract.CurrentSchemaVersion,
                data.metadata?.schemaVersion);
            AssertMaterializedConstructorRow(data, P61MaterializedTrackId);
            AssertMaterializedConstructorRow(data, P61MaterializedSegmentId);

            var first = AssertMaterializedConstructorRow(
                data,
                P61FirstUnorderedFrameId);
            var second = AssertMaterializedConstructorRow(
                data,
                P61SecondUnorderedFrameId);
            Assert.IsNotNull(first.containerId);
            Assert.AreEqual(first.containerId, second.containerId);

            NeoClient? client = null;
            Assert.DoesNotThrow(() => client = NeoTestSaveStack.LoadClient(json));
            Assert.IsNotNull(client);
            Assert.IsEmpty(
                client!.sessionValues,
                "Declaration validation must reclaim its temporary Session graph.");
        }

        private static MemberValue AssertMaterializedConstructorRow(
            ProjectData data,
            string valueId)
        {
            Assert.IsTrue(data.values.TryGetValue(valueId, out MemberValue? row));
            Assert.IsNotNull(row);
            Assert.IsNull(row!.init);
            Assert.IsNotNull(row.constructorArgs);
            Assert.IsNotEmpty(row.constructorArgs!);
            Assert.IsNotNull(row.classId);
            return row;
        }

        [Test]
        public void AnimationMemberMetadata_RoundTripsPartialFunctionRefAndUiBody()
        {
            const string classJson = @"{
  'id':'partial','projectId':'project','name':'Overrides','kind':7,

  'classId':'target','payload':1,'createdAt':'x','updatedAt':'x'
}";
            var partial = (ClassMember)JsonConvert.DeserializeObject<Member>(classJson)!;
            Assert.AreEqual(true, partial.Payload == NeoMemberPayloadKind.Partial);

            const string genericJson = @"{
  'id':'generic-partial','projectId':'project','name':'Overrides','kind':21,

  'genericParamId':'target-param','payload':1,'createdAt':'x','updatedAt':'x'
}";
            var generic = (GenericMember)JsonConvert.DeserializeObject<Member>(genericJson)!;
            Assert.AreEqual(true, generic.Payload == NeoMemberPayloadKind.Partial);

            const string functionRefJson = @"{
  'id':'action-ref','projectId':'project','name':'Action','kind':24,
  'requirement':1,
  'defaultValue':{'value':{'functionMemberId':'function-a'}},
  'createdAt':'x','updatedAt':'x'
}";
            var functionRef = (FunctionRefMember)JsonConvert.DeserializeObject<Member>(functionRefJson)!;
            Assert.AreEqual(24, (int)functionRef.kind);
            Assert.AreEqual("function-a", functionRef.defaultValue!.value!["functionMemberId"]);

            const string nsFunctionJson = @"{
  'id':'ui-function','projectId':'project','name':'OnFrame','kind':23,

  'code':'return;','bodyMode':1,'returnTypeInfo':{'type':'Void','required':true},
  'argumentTypes':[],'createdAt':'x','updatedAt':'x',
  'uiAction':{'parameters':[],'instructions':[],'typeInfo':{'type':0,'required':true}},
  'action':{'parameters':[],'instructions':[],'typeInfo':{'type':0,'required':true}}
}";
            var nsFunction = (NSFunctionMember)JsonConvert.DeserializeObject<Member>(nsFunctionJson)!;
            Assert.AreEqual(NeoFunctionBodyKind.UI, nsFunction.BodyMode);
            Assert.IsNotNull(nsFunction.uiAction);

            JObject serialized = JObject.Parse(JsonConvert.SerializeObject(nsFunction));
            Assert.AreEqual(1, serialized.Value<int>("bodyMode"));
            Assert.IsNotNull(serialized["uiAction"]);

            const string placedChildJson = @"{
  'id':'placed-child','classId':'sprite-child','sourceValueId':'authored-child',
  'createdAt':'x','updatedAt':'x','value':{}
}";
            var placedChild = (ObjectMemberValue)JsonConvert
                .DeserializeObject<MemberValue>(placedChildJson)!;
            Assert.AreEqual("authored-child", placedChild.sourceValueId);
            JObject serializedChild = JObject.Parse(
                JsonConvert.SerializeObject(placedChild));
            Assert.AreEqual(
                "authored-child",
                serializedChild.Value<string>("sourceValueId"));
        }

        [Test]
        public void NSPropertySetter_RoundTripsAuthoredCodeCompiledIrAndWritability()
        {
            var typeInfo = new PrimitiveTypeInfo
            {
                type = MemberKind.Int,
                required = true,
            };
            var source = new NSPropertyMember
            {
                id = "property-with-setter",
                projectId = "project",
                name = "Score",
                kind = MemberKind.NSProperty,
                Access = NeoMemberAccessKind.Public,
                code = "return root.Save.Score;",
                returnTypeInfo = typeInfo,
                getter = new FunctionWithReturnType
                {
                    parameters = System.Array.Empty<Variable>(),
                    instructions = System.Array.Empty<Instruction>(),
                    typeInfo = typeInfo,
                },
                setterCode = "root.Save.Score = value;",
                setter = new FunctionWithReturnType
                {
                    parameters = System.Array.Empty<Variable>(),
                    instructions = new Instruction[]
                    {
                        new AssignInstruction
                        {
                            type = InstructionKind.Assign,
                            target = new WriteTarget
                            {
                                pointer = new ReferencePointer
                                {
                                    type = PointerKind.Reference,
                                    valueId = "score-value",
                                },
                                typeInfo = typeInfo,
                                writability = WritabilityKind.Setter,
                            },
                            operatorValue = "=",
                            pointer = new VariablePointer
                            {
                                type = PointerKind.Variable,
                                variableId = "__value__",
                            },
                        },
                    },
                    typeInfo = new PrimitiveTypeInfo
                    {
                        type = MemberKind.Null,
                        required = true,
                    },
                },
                createdAt = "x",
                updatedAt = "x",
                Modifier = NeoMemberModifierKind.Static,
            };

            string json = JsonConvert.SerializeObject(source);
            var roundTripped = (NSPropertyMember)JsonConvert
                .DeserializeObject<Member>(json)!;

            Assert.AreEqual(source.setterCode, roundTripped.setterCode);
            Assert.IsTrue(roundTripped.Modifier == NeoMemberModifierKind.Static);
            Assert.IsNotNull(roundTripped.setter);
            var assign = (AssignInstruction)roundTripped.setter!.instructions[0];
            Assert.AreEqual(WritabilityKind.Setter, assign.target.writability);
            Assert.AreEqual("__value__", ((VariablePointer)assign.pointer).variableId);
        }

        [Test]
        public void WriteTarget_RuntimeWritabilityAndSchemaEightVocabularyRoundTrip()
        {
            var source = new WriteTarget
            {
                pointer = new ReferencePointer
                {
                    type = PointerKind.Reference,
                    valueId = "runtime-value",
                },
                typeInfo = new PrimitiveTypeInfo
                {
                    type = MemberKind.Int,
                    required = true,
                },
                writability = WritabilityKind.Runtime,
            };

            var roundTripped = JsonConvert.DeserializeObject<WriteTarget>(
                JsonConvert.SerializeObject(source))!;

            Assert.AreEqual("runtime", roundTripped.writability);
            Assert.AreEqual("immutable", WritabilityKind.Immutable);
            Assert.AreEqual("immutableToSaveLookup", WritabilityKind.ImmutableToSaveLookup);
            Assert.AreEqual("immutableToSessionLookup", WritabilityKind.ImmutableToSessionLookup);
        }

        [Test]
        public void ReferencePointer_ProvenanceOptInRoundTripsAndAbsentFlagStaysAbsent()
        {
            var source = new ReferencePointer
            {
                type = PointerKind.Reference,
                valueId = "authored-child",
                withProvenance = true,
            };

            string json = JsonConvert.SerializeObject(source);
            var roundTripped = (ReferencePointer)JsonConvert.DeserializeObject<Pointer>(json)!;

            StringAssert.Contains("\"withProvenance\":true", json);
            Assert.AreEqual(true, roundTripped.withProvenance);
            StringAssert.DoesNotContain(
                "withProvenance",
                JsonConvert.SerializeObject(new ReferencePointer
                {
                    type = PointerKind.Reference,
                    valueId = "exact-child",
                }));
        }

        /// <summary>
        /// P43 §1 — a computed member default carries source plus compiled IR
        /// and no baked <c>value</c>.
        /// </summary>
        [Test]
        public void MemberDefault_InitBodyRoundTrips()
        {
            const string json = @"{
  ""id"": ""member-loud"",
  ""projectId"": ""project"",
  ""name"": ""Loud"",
  ""kind"": 3,
  ""requirement"": 1,
  ""defaultValue"": {
    ""init"": {
      ""code"": ""StaticFunc(\""bar\"")"",
      ""compiled"": {
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 3, ""required"": true }
      }
    }
  },
  ""createdAt"": ""x"",
  ""updatedAt"": ""x""
}";

            var member = (StringMember)JsonConvert.DeserializeObject<Member>(json)!;

            Assert.IsNotNull(member.defaultValue!.init);
            Assert.AreEqual("StaticFunc(\"bar\")", member.defaultValue.init!.code);
            Assert.AreEqual(3, member.defaultValue.init.compiled!.compilerRevision);
            Assert.IsNull(member.defaultValue.value);
            Assert.IsNull(member.defaultValue.classId);
        }

        /// <summary>
        /// P43 §1.1a / P61 §3 — a row inside a member-default declaration
        /// graph may carry an initializer. An instance row may not.
        /// </summary>
        [Test]
        public void MemberDefaultGraphRow_InitBodyRoundTrips()
        {
            const string json = @"{
  ""id"": ""value-eyes-left"",
  ""projectId"": ""project"",
  ""init"": { ""code"": ""new EyePart(IsRight: false)"" },
  ""createdAt"": ""x"",
  ""updatedAt"": ""x""
}";

            var row = JsonConvert.DeserializeObject<MemberValue>(json)!;

            Assert.AreEqual("value-eyes-left", row.id);
            Assert.AreEqual("new EyePart(IsRight: false)", row.init!.code);
            Assert.IsNull(row.init.compiled);
        }

        /// <summary>
        /// P61 §3 / §5.1 — a materialized instance exposes its concrete
        /// graph as <c>value</c> and preserves evaluated constructor arguments
        /// as heterogeneous data. Unity reads the graph and never evaluates
        /// the creation record.
        /// </summary>
        [Test]
        public void MaterializedInstance_ConstructorArgsRoundTripAsData()
        {
            const string json = @"{
  ""id"": ""value-foo"",
  ""projectId"": ""project"",
  ""classId"": ""class-foo"",
  ""instanceConstructorId"": ""constructor-foo"",
  ""value"": {
    ""Bar"": ""value-bar"",
    ""Selector"": ""value-selector""
  },
  ""constructorArgs"": {
    ""param-bar"": ""bar"",
    ""param-count"": 3,
    ""param-child"": ""value-child"",
    ""param-selector"": {
      ""kind"": ""inline"",
      ""code"": ""() => this.Bar""
    }
  },
  ""createdAt"": ""x"",
  ""updatedAt"": ""x""
}";

            var row = (ObjectMemberValue)JsonConvert
                .DeserializeObject<MemberValue>(json)!;

            Assert.AreEqual("class-foo", row.classId);
            Assert.AreEqual("value-bar", row.value!["Bar"]);
            Assert.IsNull(row.init);
            Assert.AreEqual("bar", row.constructorArgs!["param-bar"]!.Value<string>());
            Assert.AreEqual(3, row.constructorArgs["param-count"]!.Value<int>());
            Assert.AreEqual(
                "value-child",
                row.constructorArgs["param-child"]!.Value<string>());
            Assert.AreEqual(
                "() => this.Bar",
                row.constructorArgs["param-selector"]!["code"]!.Value<string>());

            JObject serialized = JObject.Parse(JsonConvert.SerializeObject(row));
            Assert.IsNull(serialized["init"]);
            Assert.IsTrue(JToken.DeepEquals(
                JObject.Parse(json)["constructorArgs"],
                serialized["constructorArgs"]));
        }

        [Test]
        public void DeclarationRow_CarryingInitAndConstructorArgsIsRejected()
        {
            const string json = @"{
  ""id"": ""value-conflict"",
  ""projectId"": ""project"",
  ""init"": { ""code"": ""new Foo(bar: \""bar\"")"" },
  ""constructorArgs"": { ""param-bar"": ""bar"" },
  ""createdAt"": ""x"",
  ""updatedAt"": ""x""
}";

            var error = Assert.Throws<JsonSerializationException>(() =>
                JsonConvert.DeserializeObject<MemberValue>(json));

            Assert.That(
                error!.Message,
                Does.Contain("carries both 'constructorArgs' and 'init'"));
        }

