        /// <summary>
        /// P43 §6.2 — the hydrated constructor record, and §6.3's ordered
        /// <c>constructorIds</c> on the class that owns it.
        /// </summary>
        [Test]
        public void ConstructorRecord_AndClassConstructorIdsRoundTrip()
        {
            const string json = @"{
  ""metadata"": { ""schemaVersion"": 31, ""projectId"": ""project"", ""versionId"": ""v"" },
  ""project"": { ""id"": ""project"", ""name"": ""P"" },
  ""members"": {},
  ""values"": {},
  ""enums"": {},
  ""classes"": {
    ""class-foo"": {
      ""id"": ""class-foo"",
      ""projectId"": ""project"",
      ""name"": ""Foo"",
      ""schema"": {},
      ""constructorIds"": [""ctor-foo"", ""ctor-foo-loud""],
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    }
  },
  ""constructors"": {
    ""ctor-foo"": {
      ""id"": ""ctor-foo"",
      ""projectId"": ""project"",
      ""classId"": ""class-foo"",
      ""argumentTypes"": [{ ""name"": ""AllCaps"", ""type"": 1, ""required"": true }],
      ""code"": ""\t\tif (AllCaps) {\n\t\t\tthis.Bar = \""BAR\"";\n\t\t}"",
      ""action"": {
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 0, ""required"": true }
      },
      ""baseArguments"": [{ ""name"": ""Seed"", ""code"": ""AllCaps"" }],
      ""compiledBaseArguments"": [{
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 1, ""required"": true }
      }],
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    }
  }
}";

            var data = Deserialize(json);

            Assert.That(
                data.classes["class-foo"].constructorIds,
                Is.EqualTo(new[] { "ctor-foo", "ctor-foo-loud" }));
            ConstructorRecord record = data.constructors["ctor-foo"];
            Assert.AreEqual("class-foo", record.classId);
            Assert.AreEqual("AllCaps", record.argumentTypes[0].name);
            Assert.AreEqual(MemberKind.Bool, record.argumentTypes[0].type);
            Assert.AreEqual(MemberKind.Null, record.action.typeInfo.type);
            Assert.IsTrue(record.action.typeInfo.required);
            Assert.AreEqual("Seed", record.baseArguments![0].name);
            Assert.AreEqual("AllCaps", record.baseArguments[0].code);
            Assert.AreEqual(1, record.compiledBaseArguments!.Length);
        }

        /// <summary>
        /// P49 §1.1/§1.5 — a required constructor is reached through its own
        /// class field rather than <c>constructorIds</c>, and a base clause may
        /// carry an initializer block beside its arguments.
        /// </summary>
        [Test]
        public void RequiredConstructorId_AndBaseInitializerFieldsRoundTrip()
        {
            const string json = @"{
  ""metadata"": { ""schemaVersion"": 31, ""projectId"": ""project"", ""versionId"": ""v"" },
  ""project"": { ""id"": ""project"", ""name"": ""P"" },
  ""members"": {},
  ""values"": {},
  ""enums"": {},
  ""classes"": {
    ""class-bar"": {
      ""id"": ""class-bar"",
      ""projectId"": ""project"",
      ""name"": ""Bar"",
      ""schema"": {},
      ""extendsClassId"": ""class-foo"",
      ""requiredConstructorId"": ""ctor-bar"",
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    }
  },
  ""constructors"": {
    ""ctor-bar"": {
      ""id"": ""ctor-bar"",
      ""projectId"": ""project"",
      ""classId"": ""class-bar"",
      ""argumentTypes"": [{ ""name"": ""bar"", ""type"": 3, ""required"": true }],
      ""code"": """",
      ""action"": {
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 0, ""required"": true }
      },
      ""baseInitializerFields"": [{ ""name"": ""Bar"", ""code"": ""bar"" }],
      ""compiledBaseInitializerFields"": [{
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 3, ""required"": true }
      }],
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    }
  }
}";

            var data = Deserialize(json);

            Assert.AreEqual(
                "ctor-bar",
                data.classes["class-bar"].requiredConstructorId);
            Assert.IsNull(data.classes["class-bar"].constructorIds);
            ConstructorRecord record = data.constructors["ctor-bar"];
            Assert.AreEqual("", record.code);
            Assert.AreEqual("Bar", record.baseInitializerFields![0].name);
            Assert.AreEqual("bar", record.baseInitializerFields[0].code);
            Assert.AreEqual(1, record.compiledBaseInitializerFields!.Length);
            Assert.IsNull(record.baseArguments);
        }

        /// <summary>
        /// P49 §1.2 — a required constructor that declares no <c>init</c> block
        /// exports no authored code, so the field arrives as an explicit JSON
        /// null (and, from an older writer, not at all). Both mean the same
        /// thing as the <c>""</c> the test above pins: an empty body.
        /// </summary>
        [Test]
        public void ConstructorCode_IsAbsentWhenNoInitBlockIsDeclared()
        {
            const string json = @"{
  ""metadata"": { ""schemaVersion"": 31, ""projectId"": ""project"", ""versionId"": ""v"" },
  ""project"": { ""id"": ""project"", ""name"": ""P"" },
  ""members"": {},
  ""values"": {},
  ""enums"": {},
  ""classes"": {
    ""class-bar"": {
      ""id"": ""class-bar"",
      ""projectId"": ""project"",
      ""name"": ""Bar"",
      ""schema"": {},
      ""requiredConstructorId"": ""ctor-null"",
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    }
  },
  ""constructors"": {
    ""ctor-null"": {
      ""id"": ""ctor-null"",
      ""projectId"": ""project"",
      ""classId"": ""class-bar"",
      ""argumentTypes"": [{ ""name"": ""bar"", ""type"": 3, ""required"": true }],
      ""code"": null,
      ""action"": {
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 0, ""required"": true }
      },
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    },
    ""ctor-omitted"": {
      ""id"": ""ctor-omitted"",
      ""projectId"": ""project"",
      ""classId"": ""class-bar"",
      ""argumentTypes"": [],
      ""action"": {
        ""compilerRevision"": 3,
        ""parameters"": [],
        ""instructions"": [],
        ""typeInfo"": { ""type"": 0, ""required"": true }
      },
      ""createdAt"": ""x"",
      ""updatedAt"": ""x""
    }
  }
}";

            var data = Deserialize(json);

            ConstructorRecord explicitNull = data.constructors["ctor-null"];
            Assert.IsNull(explicitNull.code);
            // The rest of the record still has to land — a null body is not a
            // truncated record.
            Assert.AreEqual("bar", explicitNull.argumentTypes[0].name);
            Assert.AreEqual(MemberKind.Null, explicitNull.action.typeInfo.type);
            Assert.IsNull(data.constructors["ctor-omitted"].code);
        }

        /// <summary>
        /// P43 §6.1 — the <c>declaredConstructor</c> IR variant, which is
        /// distinct from the schema-derived <c>classConstructor</c>.
        /// </summary>
        [Test]
        public void DeclaredConstructorFunction_RoundTrips()
        {
            const string json = @"{
  ""type"": ""declaredConstructor"",
  ""info"": {
    ""schemaClassInfo"": { ""type"": 7, ""required"": true, ""classId"": ""class-foo"" },
    ""constructorId"": ""ctor-foo"",
    ""args"": [{
      ""name"": ""AllCaps"",
      ""valuePointer"": {
        ""type"": ""value"",
        ""value"": { ""typeInfo"": { ""type"": 1, ""required"": true }, ""value"": true }
      }
