    ""fields"": [{
      ""schemaKey"": ""Bar"",
      ""memberId"": ""member-foo-bar"",
      ""valuePointer"": {
        ""type"": ""value"",
        ""value"": { ""typeInfo"": { ""type"": 3, ""required"": true }, ""value"": ""custom"" }
      }
